'use strict';
const serviceQuantityFields=(p,value={})=>THServices.weighted(p)?field('Berat laundry (kg)','weight','number',value.weight||0,'min="0" max="1000" step="0.01" required'):field('Jumlah barang ('+p.unit+')','quantity','number',value.quantity||0,'min="0" max="1000" step="1" required')+field('Berat fisik (kg, opsional)','weight','number',value.weight||'','min="0" max="1000" step="0.01"');
function serviceSetting(p,i){p=THServices.normalize(p);return `<details class="service-setting" data-package-index="${i}"><summary><strong>${esc(p.name||'Layanan baru')}</strong><span>${money(p.price)} / ${esc(p.unit)} · ${THServices.duration(p)}</span></summary><div class="form-grid">${field('ID layanan','packageId'+i,'hidden',p.id)}${field('Nama layanan','packageName'+i,'text',p.name,'required maxlength="100"')}${field('Harga per satuan (Rp)','packagePrice'+i,'number',p.price||'','min="1" max="1000000" required')}${select('Satuan','packageUnit'+i,THServices.units,p.unit)}${field('Waktu pengerjaan (jam)','packageHours'+i,'number',p.hours||48,'min="1" max="240" required')}${field('Minimal jumlah (0 = tanpa minimum)','packageMin'+i,'number',p.minQuantity,'min="0" max="100" step="0.01" required')}${field('Kapasitas kg per load (khusus Load)','packageLoad'+i,'number',p.loadKg||2,'min="0.1" max="100" step="0.1" required')}${field('Kategori','packageCategory'+i,'text',p.category,'maxlength="60"')}</div>${btn('Hapus layanan','package-remove',String(i),'text-btn danger')}</details>`;}
function serviceFromFields(v,i){const p={id:v['packageId'+i]||'custom-'+uid(),name:requireText(v['packageName'+i],'Nama layanan'),price:finite(v['packagePrice'+i],'Harga',1,1e6),hours:finite(v['packageHours'+i],'Target jam',1,240),unit:v['packageUnit'+i]||'KG',minQuantity:Number(v['packageMin'+i]||0),loadKg:v['packageUnit'+i]==='Load'?Number(v['packageLoad'+i]||2):0,category:v['packageCategory'+i]||'Lainnya'};if(!THServices.valid(p))throw Error('Periksa satuan, harga, minimum, dan kapasitas layanan '+p.name+'.');return p;}
(function(){
const S=THServices;
const localTime=v=>v?THJournalCore.local(v):'';
const roomTypes=['Non-AC','AC','Superior','Deluxe','Executive','Grand Executive'];
function stayFields(t={},prefix=''){const val=k=>t[k]||'';return `${field('Nama pelanggan',prefix+'name','text',val('name'),'required maxlength="70" autocomplete="name"')}${field('Nomor WhatsApp / kontak',prefix+'contact','tel',val('contact'),'required maxlength="40" autocomplete="tel"')}${select('Jenis pelanggan',prefix+'type',['Kost putri','Penginapan','Umum'],t.type||'Penginapan')}${field('Gedung',prefix+'building','text',val('building'),'required maxlength="30" list="th-buildings" placeholder="Contoh: C"')}${field('Lantai',prefix+'floor','text',val('floor'),'required maxlength="20" placeholder="Contoh: 2 / Dasar"')}${field('Nomor / kode kamar',prefix+'room','text',val('room'),'required maxlength="30" placeholder="Contoh: D01"')}${field('Jenis kamar',prefix+'roomType','text',val('roomType'),'required maxlength="60" list="th-room-types" placeholder="Pilih atau tulis jenis kamar"')}${field('Checkout / akhir tinggal (WIB)',prefix+'checkout','datetime-local',localTime(t.checkout||(t.type==='Penginapan'&&t.end?t.end+'T12:00:00+07:00':'')),'')}`;}
const lists=()=>`<datalist id="th-buildings"><option>A</option><option>B</option><option>C</option></datalist><datalist id="th-room-types">${roomTypes.map(t=>'<option>'+t+'</option>').join('')}</datalist>`;
function toggleStay(form,prefix=''){const type=form.elements[prefix+'type'].value,publicCustomer=type==='Umum';for(const k of ['building','floor','room','roomType']){const el=form.elements[prefix+k];el.closest('.field').hidden=publicCustomer;el.disabled=publicCustomer;el.required=!publicCustomer;}const checkout=form.elements[prefix+'checkout'];checkout.closest('.field').hidden=publicCustomer;checkout.disabled=publicCustomer;checkout.required=type==='Penginapan';if(form.elements[prefix+'address']){const el=form.elements[prefix+'address'];el.closest('.field').hidden=!publicCustomer;el.disabled=!publicCustomer;el.required=publicCustomer;}}
function stayData(v,prefix='',prior){const take=k=>String(v[prefix+k]||'').trim();const type=take('type');if(!['Kost putri','Penginapan','Umum'].includes(type))throw Error('Pilih jenis pelanggan.');const data={name:requireText(take('name'),'Nama pelanggan'),contact:requireText(take('contact'),'Kontak'),type};if(type==='Umum')return {...data,room:requireText(take('address'),'Alamat / titik serah'),building:'',floor:'',roomType:'',checkout:''};for(const k of ['building','floor','room','roomType'])data[k]=requireText(take(k),{building:'Gedung',floor:'Lantai',room:'Nomor kamar',roomType:'Jenis kamar'}[k]);const checkout=take('checkout');if(type==='Penginapan'&&!checkout)throw Error('Tanggal dan jam checkout penginapan wajib diisi.');if(checkout&&!Number.isFinite(THJournalCore.timestamp(checkout)))throw Error('Tanggal checkout tidak valid.');return {...data,checkout:checkout?checkout+'+07:00':'',end:checkout?checkout.slice(0,10):prior?.end||''};}
function duplicateStay(data,except=''){if(data.type==='Umum')return;const same=x=>String(x||'').trim().toLowerCase();const duplicate=db.tenants.find(t=>t.id!==except&&t.status==='Aktif'&&same(t.name)===same(data.name)&&same(t.contact)===same(data.contact)&&same(t.building)===same(data.building)&&same(t.floor)===same(data.floor)&&same(t.room)===same(data.room)&&(!t.end||t.end>=ui.date));if(duplicate)throw Error('Pelanggan ini sudah terdaftar. Pilih '+duplicate.name+' dari daftar pelanggan.');}
function fillCustomer(form,t){for(const k of ['name','contact','type','building','floor','room','roomType'])form.elements['customer'+k].value=t[k]|| (k==='type'?'Penginapan':'');form.elements.customercheckout.value=localTime(t.checkout||(t.type==='Penginapan'&&t.end?t.end+'T12:00:00+07:00':''));form.elements.customeraddress.value=t.type==='Umum'?t.room||'':'';toggleStay(form,'customer');}
newOrder=function(prefill={}){canEdit();if(!db.settings.packages.length||!db.employees.some(e=>e.active)){openModal('Siapkan petugas laundry',`<p>Daftar layanan sudah tersedia. Tambahkan karyawan aktif untuk menjadi penanggung jawab pesanan.</p>${ui.role==='Owner'?btn('Tambah karyawan','new-employee','','btn primary','plus'):'<p>Hubungi Owner untuk menyiapkan petugas.</p>'}`);return;}const services=db.settings.packages.map(S.normalize),selected=Math.max(0,services.findIndex(p=>p.id===(prefill.serviceId||'THL-regular-refresh'))),p=services[selected],tenant=getTenant(prefill.tenantId),mode=prefill.mode||'Antar langsung',defaultQty=mode==='Jemput'?0:Math.max(p.minQuantity,1);openModal('Catat laundry baru',`<form data-form="order" class="laundry-order-form"><div class="order-form-intro"><span class="eyebrow">LDR-${String(db.settings.labelNext).padStart(4,'0')}</span><span>Harga dan target mengikuti layanan pilihan.</span></div><section class="order-form-section"><h3><span>1</span> Pelanggan & lokasi</h3>${select('Pilih pelanggan','tenantId',[['new','+ Pelanggan baru'],...db.tenants.filter(t=>t.status==='Aktif').map(t=>[t.id,t.name+' · '+S.location(t)])],tenant?.id||'new')}<p class="form-note" id="customer-form-note">Pelanggan baru bisa langsung dicatat bersama order ini.</p><div class="form-grid">${stayFields(tenant||{type:'Penginapan'},'customer')}${field('Alamat / titik serah','customeraddress','text','','maxlength="160"')}</div>${lists()}</section><section class="order-form-section"><h3><span>2</span> Layanan & jumlah</h3>${field('Cari layanan','serviceSearch','search','','placeholder="Coba: bed cover, express, setrika…" autocomplete="off"')}${select('Layanan laundry','package',services.map((p,i)=>[i,`${p.name} · ${money(p.price)} / ${p.unit}`]),selected)}<div class="service-facts" id="service-facts"></div><div class="form-grid" id="service-quantity-fields">${serviceQuantityFields(p,{weight:S.weighted(p)?defaultQty:0,quantity:defaultQty})}</div><div class="service-estimate" id="price-preview" role="status" aria-live="polite"></div></section><section class="order-form-section"><h3><span>3</span> Penerimaan & penyerahan</h3><div class="form-grid">${select('Jalur penerimaan','mode',['Antar langsung','Jemput'],mode)}${field('Jumlah kantong','bags','number',prefill.bags||1,'min="1" max="26" step="1" required')}${select('Petugas penanggung jawab','pic',db.employees.filter(e=>e.active).map(e=>[e.id,e.name]),ui.employee)}${select('Pengembalian','returnMode',['Ambil di counter','Antar ke kamar'],prefill.returnMode||'Ambil di counter')}${field('Target selesai (WIB)','due','datetime-local',dueFor(p.hours),'required')}${area('Catatan / waktu jemput / instruksi penyerahan','note',prefill.note||'','maxlength="1000"')}</div><div id="checkout-warning" class="notice yellow" hidden></div>${check('Jika target melewati checkout: alternatif disetujui Owner dan pelanggan','checkoutApproval')}</section><details class="evidence-box" open><summary>Bukti penerimaan</summary><p class="form-note">Tandai bukti yang tersedia. Bukti transaksi keuangan dilampirkan melalui menu Laporan.</p>${check('Jejak permintaan / check-in pelanggan tersedia','chat',false)}${check('Label terpasang pada semua kantong','label',false)}${check('Bukti timbang / hitung barang sesuai layanan tersedia','weigh',false)}${check('Resi telah diperiksa pelanggan','receipt',false)}</details>${field('ID permintaan portal','requestId','hidden',prefill.requestId||'')}${formFoot('Simpan pelanggan & order','Pelanggan penginapan/kost baru masuk ke daftar Penghuni. Data sewa dapat dilengkapi kemudian; tidak membuat tagihan hunian otomatis.')}</form>`,true);const form=dialog.querySelector('[data-form="order"]');toggleStay(form,'customer');updateOrderEstimate();};
updateOrderEstimate=function(changedName){const form=dialog.querySelector('[data-form="order"]');if(!form)return;const v=Object.fromEntries(new FormData(form)),p=S.normalize(db.settings.packages[Number(v.package)]||db.settings.packages[0]);if(changedName==='tenantId'){const t=getTenant(v.tenantId);fillCustomer(form,t||{type:'Penginapan'});form.querySelector('#customer-form-note').textContent=t?'Data tersimpan terisi otomatis. Perubahan lokasi disimpan bersama order.':'Pelanggan penginapan/kost baru akan masuk ke daftar Penghuni.';}
 if(changedName==='customertype')toggleStay(form,'customer');
 if(changedName==='package'){const n=form.elements.mode.value==='Jemput'?0:Math.max(1,p.minQuantity);form.querySelector('#service-quantity-fields').innerHTML=serviceQuantityFields(p,{weight:S.weighted(p)?n:0,quantity:n});form.elements.due.value=dueFor(p.hours);}
 if(changedName==='mode'&&v.mode==='Jemput'){form.elements.weight.value=0;if(form.elements.quantity)form.elements.quantity.value=0;['label','weigh','receipt'].forEach(k=>form.elements[k].checked=false);}
 const facts=form.querySelector('#service-facts');facts.innerHTML=`${badge(S.duration(p),'blue')}${badge(p.unit==='Load'?p.loadKg+' kg / load':p.unit,'neutral')}<span>${esc(S.rule(p))}</span>`;
 const now=Object.fromEntries(new FormData(form)),price=form.querySelector('#price-preview');let q;try{q=S.quote(p,Number(now.weight||0),Number(now.quantity||0));}catch(err){price.textContent=err.message;return;}price.innerHTML=`<span>Estimasi tagihan</span><strong>${money(q.total)}</strong><small>${q.quantity?`${q.billedQuantity} ${p.unit} × ${money(p.price)}`:'Jumlah final dicatat saat laundry diterima.'}${q.minimumMet?'':' · '+S.rule(p)}</small>`;price.classList.toggle('below-minimum',!q.minimumMet);
 const checkout=now.customercheckout,warning=form.querySelector('#checkout-warning'),late=!!checkout&&THJournalCore.timestamp(now.due)>THJournalCore.timestamp(checkout);warning.hidden=!late;warning.textContent=late?'Target layanan melewati checkout. Pilih layanan lebih cepat, sesuaikan target, atau sepakati penyerahan alternatif.':'';
};
submissions.order=function(v){canEdit();const s=db.settings;if(s.labelNext>s.labelEnd)throw Error('Rentang label habis. Hubungi Owner.');const prior=getTenant(v.tenantId);if(v.tenantId!=='new'&&!prior)throw Error('Pilih pelanggan.');if(!db.employees.some(e=>e.id===v.pic&&e.active))throw Error('Pilih petugas aktif.');const p=S.normalize(s.packages[Number(v.package)]),customer=stayData(v,'customer',prior);if(prior&&customer.type==='Umum')throw Error('Profil hunian tetap memakai jenis kost atau penginapan. Pilih Pelanggan baru untuk customer umum.');duplicateStay(customer,prior?.id);const weight=finite(v.weight||0,'Berat',0,1000),quantity=finite(v.quantity||0,'Jumlah barang',0,1000),q=S.quote(p,weight,quantity),bags=finite(v.bags,'Jumlah kantong',1,26);if(!Number.isInteger(bags))throw Error('Jumlah kantong harus bulat.');if(!q.minimumMet)throw Error(S.rule(p));if(!v.chat)throw Error('Jejak permintaan pelanggan wajib tersedia.');const created=new Date().toISOString(),due=THJournalCore.timestamp(v.due);if(!Number.isFinite(due)||due<Date.parse(created))throw Error('Target selesai tidak boleh sebelum penerimaan.');if(customer.checkout&&due>THJournalCore.timestamp(customer.checkout)&&!v.checkoutApproval)throw Error('Target melewati checkout. Catat persetujuan alternatif atau ubah layanan/target.');if(v.mode==='Antar langsung'&&(!q.quantity||!v.label||!v.weigh||!v.receipt))throw Error('Antar langsung memerlukan jumlah final, label, bukti timbang/hitung, dan resi.');if(!['Antar langsung','Jemput'].includes(v.mode))throw Error('Jalur penerimaan tidak valid.');const request=v.requestId?db.requests.find(r=>r.id===v.requestId):null;if(v.requestId&&(!request||request.status!=='Baru'||request.tenantId!==prior?.id))throw Error('Permintaan tidak sesuai pelanggan atau sudah diproses.');const tenantId=customer.type==='Umum'?'':prior?.id||uid(),id='LDR-'+String(s.labelNext).padStart(4,'0');if(db.orders.some(x=>x.id===id))throw Error('Nomor label sudah terpakai.');const o={id,tenantId,customer:customer.name,contact:customer.contact,type:customer.type,room:customer.room,building:customer.building,floor:customer.floor,roomType:customer.roomType,mode:v.mode,bags,weight,quantity:q.quantity,billedQuantity:q.billedQuantity,serviceSnapshot:p,package:p.name,rate:p.price,total:q.total,stage:v.mode==='Antar langsung'?'Diterima Laundry':'Pesanan Masuk',payment:'Belum Bayar',method:'QRIS',pic:v.pic,created,due:v.due+'+07:00',checkout:customer.checkout,returnMode:v.returnMode,recipient:'',note:v.note||'',evidence:{chat:!!v.chat,label:!!v.label,weigh:!!v.weigh,receipt:!!v.receipt,checkoutApproval:!!v.checkoutApproval},history:[]};S.validateOrder(o,null,s.packages,ui.role);
 if(tenantId){if(prior)Object.assign(prior,customer,{updatedAt:created});else db.tenants.push({id:tenantId,...customer,start:'',rent:0,rentKnown:false,laundryOnly:true,note:'Ditambahkan saat penerimaan laundry.',status:'Aktif',createdAt:created});audit((prior?'Pelanggan diperbarui: ':'Pelanggan ditambahkan: ')+customer.name+' · '+S.location(customer));}db.orders.unshift(o);s.labelNext++;history(o,'Order dicatat · '+S.quantityText(o)+' · '+S.location(o));if(request){request.status='Diproses · '+id;request.orderId=id;}return 'Order '+id+' tersimpan'+(tenantId&&!prior?' bersama pelanggan baru.':'.');};
tenantForm=function(id){canEdit();const t=getTenant(id)||{type:'Kost putri',status:'Aktif'};openModal(id?'Kelola pelanggan hunian':'Tambah pelanggan hunian',`<form data-form="tenant" data-id="${id||''}" class="laundry-order-form"><div class="form-grid">${stayFields(t)}${select('Status penghuni','status',['Aktif','Check-out','Arsip'],t.status)}</div>${lists()}<details class="order-form-section"><summary>Data sewa & catatan (opsional)</summary><div class="form-grid">${field('Mulai tinggal','start','date',t.start||'')}${field('Akhir periode sewa','end','date',t.end||'')}${field('Nilai sewa periode (Rp)','rent','number',t.rentKnown===false?'':t.rent??'','min="0" max="1000000000"')}${area('Catatan','note',t.note||'','maxlength="1000"')}</div></details>${formFoot('Simpan pelanggan','Lokasi membantu petugas menjemput dan mengembalikan laundry. Data sewa dapat dilengkapi kemudian.')}</form>`,true);const form=dialog.querySelector('[data-form="tenant"]');form.elements.type.querySelector('option[value="Umum"]').remove();toggleStay(form);};
submissions.tenant=function(v,f){canEdit();const prior=getTenant(f.dataset.id),data=stayData(v,'',prior);if(data.type==='Umum')throw Error('Pilih jenis hunian.');data.start=v.start||'';data.end=data.checkout?data.checkout.slice(0,10):v.end||'';if(data.start&&data.end&&data.end<data.start)throw Error('Akhir tinggal harus setelah tanggal mulai.');if(data.checkout&&v.end&&v.end!==data.checkout.slice(0,10))throw Error('Samakan tanggal akhir sewa dengan tanggal checkout, atau kosongkan akhir periode sewa.');data.rentKnown=v.rent!=='';data.rent=finite(v.rent||0,'Nilai sewa');data.laundryOnly=!data.start||!data.end||!data.rentKnown;data.note=v.note||'';data.status=v.status;if(data.status==='Aktif')duplicateStay(data,prior?.id);if(prior&&data.status!=='Aktif'&&db.orders.some(o=>o.tenantId===prior.id&&!['Selesai','Dibatalkan'].includes(o.stage)))throw Error('Selesaikan laundry pelanggan sebelum checkout atau arsip.');if(prior)Object.assign(prior,data);else db.tenants.push({id:uid(),...data,createdAt:new Date().toISOString()});audit('Data pelanggan disimpan: '+data.name+' · '+S.location(data));return 'Data pelanggan tersimpan.';};
const oldTemplate=templateText;
templateText=function(i,o=db.orders[0]){if(!o)return oldTemplate(i,o);let text=oldTemplate(i,o);text=text.replace('Berat: '+o.weight+' kg','Jumlah: '+S.quantityText(o)).replace('Tarif demo: '+money(o.rate)+'/kg','Tarif: '+money(o.rate)+' / '+S.snapshot(o).unit);return text+`\nLokasi: ${S.location(o)||o.room||'—'}${o.roomType?' · '+o.roomType:''}\nKontak: ${o.contact||'—'}${o.checkout?'\nCheckout: '+datetime(o.checkout):''}`;};
actions['package-add']=()=>{const form=dialog.querySelector('[data-form="settings"]'),indices=[...form.querySelectorAll('[data-package-index]')].map(x=>+x.dataset.packageIndex),i=Math.max(-1,...indices)+1;form.querySelector('#package-add-target').insertAdjacentHTML('beforebegin',serviceSetting({name:'',price:0,hours:48,unit:'KG'},i));form.querySelector('[data-package-index="'+i+'"]').open=true;};
actions['service-catalog']=()=>{canEdit();openModal('Daftar layanan Top Hills',`<div class="catalog-heading"><p>${db.settings.packages.length} layanan · pilih untuk mulai mencatat laundry.</p>${ui.role==='Owner'?btn('Kelola harga','settings','','btn small','settings'):''}</div>${field('Cari nama atau kategori','catalogSearch','search','','placeholder="Cari layanan…"')}<div class="service-catalog">${db.settings.packages.map(p=>{p=S.normalize(p);return `<button type="button" class="service-card" data-action="service-order" data-id="${esc(p.id)}" data-service-name="${esc((p.name+' '+p.category).toLowerCase())}"><span class="eyebrow">${esc(p.category)} · ${S.duration(p)}</span><strong>${esc(p.name)}</strong><span class="service-price">${money(p.price)} <small>/ ${p.unit}</small></span><small>${esc(S.rule(p))}</small><span class="text-btn">Pilih layanan ${icon('plus')}</span></button>`}).join('')}</div><p class="form-note" id="catalog-empty" hidden>Layanan tidak ditemukan.</p>`,true);};
actions['service-order']=id=>newOrder({serviceId:id});
actions.tenant=tenantForm;
const originalLaundry=renderLaundry;renderLaundry=function(){return `<div class="service-catalog-bar"><span>${db.settings.packages.length} layanan tersedia</span>${btn('Daftar layanan & harga','service-catalog','','btn ghost','laundry')}</div>`+originalLaundry();};
// Keep typed fields in place while the operator changes service or customer type.
document.addEventListener('change',e=>{const f=e.target.closest('[data-form="tenant"]');if(f&&e.target.name==='type')toggleStay(f);});
document.addEventListener('input',e=>{if(e.target.name==='serviceSearch'){const f=e.target.form,value=e.target.value.toLowerCase(),selected=f.elements.package.value;f.elements.package.innerHTML=db.settings.packages.map((p,i)=>({p,i})).filter(({p,i})=>String(i)===selected||(p.name+' '+(p.category||'')).toLowerCase().includes(value)).map(({p,i})=>`<option value="${i}" ${String(i)===selected?'selected':''}>${esc(p.name)} · ${money(p.price)} / ${p.unit||'KG'}</option>`).join('');}if(e.target.name==='catalogSearch'){let visible=0;dialog.querySelectorAll('[data-service-name]').forEach(card=>{card.hidden=!card.dataset.serviceName.includes(e.target.value.toLowerCase());if(!card.hidden)visible++;});dialog.querySelector('#catalog-empty').hidden=!!visible;}});
})();
